<?php $e=fn($v)=>htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8'); ?>
<div class="section-heading"><div><div class="eyebrow">Continuidade</div><h1>Backups e restauração</h1><p class="text-secondary mb-0">Banco, uploads, criptografia, retenção e testes isolados.</p></div><form method="post" action="/master/backups"><?=\App\Core\CSRF::field()?><button class="btn btn-primary">Criar backup agora</button></form></div>
<?php if($success):?><div class="alert alert-success"><?=$e($success)?></div><?php endif;?><?php if($error):?><div class="alert alert-danger"><?=$e($error)?></div><?php endif;?>
<div class="alert alert-info"><strong>Teste seguro:</strong> a restauração cria uma base temporária, importa e valida as tabelas e apaga essa base. A produção nunca é sobrescrita.</div>
<div class="card"><div class="table-responsive"><table class="table align-middle mb-0"><thead><tr><th>Data</th><th>Escopo</th><th>Tamanho</th><th>Proteção</th><th>Situação</th><th>Retenção</th><th>Ações</th></tr></thead><tbody><?php foreach($backups as $backup):?><tr><td><?=date('d/m/Y H:i',strtotime($backup['started_at']))?></td><td><?=$e(($backup['scope']??'database')==='database_uploads'?'Banco + uploads':'Banco')?></td><td><?=$backup['size_bytes']!==null?number_format(((int)$backup['size_bytes'])/1048576,2,',','.').' MB':'—'?></td><td><?=!empty($backup['encrypted'])?'Criptografado':'Sem criptografia'?></td><td><span class="badge text-bg-<?=$backup['status']==='completed'?'success':($backup['status']==='failed'?'danger':'warning')?>"><?=$e($backup['status'])?></span></td><td><?=!empty($backup['expires_at'])?date('d/m/Y',strtotime($backup['expires_at'])):'—'?></td><td><?php if($backup['status']==='completed'):?><div class="d-flex gap-2"><a class="btn btn-sm btn-outline-primary" href="/master/backups/<?=(int)$backup['id']?>/download">Baixar</a><form method="post" action="/master/backups/<?=(int)$backup['id']?>/testar-restauracao"><?=\App\Core\CSRF::field()?><button class="btn btn-sm btn-outline-success" onclick="return confirm('Executar restauração isolada?')">Testar restauração</button></form></div><?php endif;?></td></tr><?php endforeach;?><?php if(!$backups):?><tr><td colspan="7"><div class="empty-state">Nenhum backup executado.</div></td></tr><?php endif;?></tbody></table></div></div>
